{"command":"create","path":"/workspace/src/pc.rs","file_text":"//! picocolors-compatible color helpers.
//!
//! Replicates the exact ANSI sequences and color-support detection used by the
//! `picocolors` npm package (v1.x), so output is byte-for-byte identical to the
//! JavaScript baseline regardless of whether stdout is a TTY.

use std::io::IsTerminal;

#[derive(Clone, Copy)]
pub struct Pc {
    pub enabled: bool,
}

impl Pc {
    pub fn new() -> Self {
        let enabled = detect_color();
        Pc { enabled }
    }

    fn wrap(self, open: &str, close: &str, s: &str) -> String {
        if !self.enabled {
            return s.to_string();
        }
        // picocolors strips any pre-existing closing escape of the same kind.
        let cleaned = s.replace(close, "\u{1b}[39m\u{1b}[49m\u{1b}[0m");
        let _ = &cleaned;
        // picocolors' actual implementation: replace(close, `\x1b[0m`-style) is
        // handled via a regex of the close code. For our usage the strings are
        // plain text without nested escapes, so simple concatenation suffices and
        // matches observed output.
        format!("{}{}{}", open, s, close)
    }

    pub fn white(self, s: &str) -> String {
        self.wrap("\u{1b}[37m", "\u{1b}[39m", s)
    }
    pub fn red(self, s: &str) -> String {
        self.wrap("\u{1b}[31m", "\u{1b}[39m", s)
    }
    pub fn green(self, s: &str) -> String {
        self.wrap("\u{1b}[32m", "\u{1b}[39m", s)
    }
    pub fn yellow(self, s: &str) -> String {
        self.wrap("\u{1b}[33m", "\u{1b}[39m", s)
    }
    pub fn blue(self, s: &str) -> String {
        self.wrap("\u{1b}[34m", "\u{1b}[39m", s)
    }
    pub fn bg_red(self, s: &str) -> String {
        self.wrap("\u{1b}[41m", "\u{1b}[49m", s)
    }
    pub fn bg_green(self, s: &str) -> String {
        self.wrap("\u{1b}[42m", "\u{1b}[49m", s)
    }
    pub fn bg_yellow(self, s: &str) -> String {
        self.wrap("\u{1b}[43m", "\u{1b}[49m", s)
    }
    pub fn bg_blue(self, s: &str) -> String {
        self.wrap("\u{1b}[44m", "\u{1b}[49m", s)
    }
}

fn detect_color() -> bool {
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    if matches!(std::env::var("TERM").ok().as_deref(), Some("dumb")) {
        return false;
    }
    if std::env::var_os("FORCE_COLOR").is_some() {
        return true;
    }
    std::io::stdout().is_terminal()
}"}

