{"command":"create","file_text":"//! Port of `src/argsParser.js` (nomnom-derived) to Rust.
//!
//! Preserves the exact option-parsing semantics of the JavaScript baseline,
//! including: unknown-option pass-through (flag vs. value vs. list promotion),
//! `--no-` flag negation, `--opt=value` and `--opt value` forms, JSON value
//! parsing for unknown options, `choices` validation, `process` functions,
//! and help/version callbacks.

use serde_json::{Map, Value};
use std::collections::HashMap;

/// A processing function applied to a supplied value.
#[derive(Clone, Copy, PartialEq)]
pub enum Process {
    None,
    Number,
    ParserConfig,
}

/// A callback that short-circuits parsing (help / version).
#[derive(Clone, Copy, PartialEq)]
pub enum Callback {
    None,
    Help,
    Version,
}

/// One declared option, mirroring the JS option object.
#[derive(Clone)]
pub struct OptionDef {
    pub key: String,
    pub full: String,
    pub abbr: Option<String>,
    pub flag: bool,
    pub list: bool,
    pub default: Option<Value>,
    pub default_help: Option<String>,
    pub choices: Option<Vec<Value>>,
    pub help: Option<String>,
    pub metavar: Option<String>,
    pub process: Process,
    pub callback: Callback,
    pub display_index: i64,
}

impl OptionDef {
    fn new(key: &str) -> Self {
        OptionDef {
            key: key.to_string(),
            full: key.to_string(),
            abbr: None,
            flag: false,
            list: false,
            default: None,
            default_help: None,
            choices: None,
            help: None,
            metavar: None,
            process: Process::None,
            callback: Callback::None,
            display_index: 0,
        }
    }
}

/// Builder for an option.
pub fn opt(key: &str) -> OptionDef {
    OptionDef::new(key)
}

pub struct ParseResult {
    pub positional_arguments: Vec<Value>,
    pub options: Map<String, Value>,
}

/// Error raised during parsing; mirrors `error.exitCode` / `error.message`.
pub struct CliError {
    pub exit_code: i32,
    pub message: String,
}

fn is_option(value: &str) -> bool {
    value.starts_with('-')
}

fn real_option_name(option_name: &str) -> String {
    // strip leading --? and optional no- prefix
    let mut s = option_name;
    let mut stripped_no = false;
    if s.starts_with("--") {
        s = &s[2..];
    } else if s.starts_with('-') {
        s = &s[1..];
    }
    if let Some(rest) = s.strip_prefix("no-") {
        s = rest;
        stripped_no = true;
    }
    let _ = stripped_no;
    s.to_string()
}

fn json_parse_fallback(value: &str) -> Value {
    // Equivalent to the unknown-option process: try JSON.parse, else keep string.
    if let Ok(v) = serde_json::from_str::<Value>(value) {
        v
    } else {
        Value::String(value.to_string())
    }
}

fn apply_process(proc_fn: Process, value: &str) -> Result<Value, CliError> {
    match proc_fn {
        Process::None => Ok(Value::String(value.to_string())),
        Process::Number => Ok(number_value(value)),
        Process::ParserConfig => {
            let content = match std::fs::read_to_string(value) {
                Ok(c) => c,
                Err(e) => {
                    return Err(CliError {
                        exit_code: 1,
                        message: e.to_string(),
                    })
                }
            };
            match serde_json::from_str::<Value>(&content) {
                Ok(v) => Ok(v),
                Err(e) => Err(CliError {
                    exit_code: 1,
                    message: e.to_string(),
                }),
            }
        }
    }
}

fn number_value(value: &str) -> Value {
    match value.parse::<f64>() {
        Ok(n) if n.is_finite() => {
            if n.fract() == 0.0 && n.abs() < 9_007_199_254_740_992.0 {
                Value::from(n as i64)
            } else {
                serde_json::Number::from_f64(n)
                    .map(Value::Number)
                    .unwrap_or(Value::Null)
            }
        }
        _ => Value::Null,
    }
}

fn positional_value(arg: &str) -> Value {
    if !arg.is_empty() && arg.bytes().all(|b| b.is_ascii_digit()) {
        // /^\d+$/
        Value::from(arg.parse::<i64>().unwrap_or(0))
    } else {
        Value::String(arg.to_string())
    }
}

/// Prepared lookup table mapping each CLI token (`--full`, `-abbr`, `--no-full`)
/// to the option it refers to (index into the options vec).
struct Prepared {
    by_token: HashMap<String, usize>,
}

fn prepare(options: &[OptionDef]) -> Prepared {
    let mut by_token = HashMap::new();
    for (i, o) in options.iter().enumerate() {
        by_token.insert(format!("--{}", o.full), i);
        if let Some(abbr) = &o.abbr {
            by_token.insert(format!("-{}", abbr), i);
        }
        if o.flag {
            by_token.insert(format!("--no-{}", o.full), i);
        }
    }
    by_token
}

pub fn parse(options: &[OptionDef], args: &[String]) -> Result<ParseResult, CliError> {
    let prepared = prepare(options);
    let mut parsed: Map<String, Value> = Map::new();
    let mut positional: Vec<Value> = Vec::new();
    let mut missing: Vec<String> = Vec::new();

    // Seed defaults / empty lists.
    for o in options {
        if let Some(d) = &o.default {
            parsed.insert(o.key.clone(), d.clone());
        } else if o.list {
            parsed.insert(o.key.clone(), Value::Array(Vec::new()));
        }
    }

    let mut i = 0;
    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name: String = arg.clone();
            let mut value: Option<String> = None;
            if let Some(eq) = arg.find('=') {
                option_name = arg[..eq].to_string();
                value = Some(arg[eq + 1..].to_string());
            }

            let (key, flag, list, process, callback, full) =
                if let Some(&idx) = prepared.by_token.get(&option_name) {
                    let o = &options[idx];
                    (
                        o.key.clone(),
                        o.flag,
                        o.list,
                        o.process,
                        o.callback,
                        o.full.clone(),
                    )
                } else {
                    // Unknown option: passed along.
                    let real = real_option_name(&option_name);
                    let has = parsed.contains_key(&real);
                    let prev_not_true = match parsed.get(&real) {
                        Some(Value::Bool(true)) => false,
                        Some(_) => true,
                        None => false,
                    };
                    let is_list = has && prev_not_true;
                    let next_is_option =
                        (i + 1 < args.len()).then(|| is_option(&args[i + 1])).unwrap_or(false);
                    let flag = !has && value.is_none() && next_is_option;
                    if is_list {
                        let cur = parsed.get(&real).cloned();
                        match cur {
                            Some(Value::Array(_)) => {}
                            Some(Value::Bool(true)) => {
                                parsed.insert(real.clone(), Value::Array(Vec::new()));
                            }
                            Some(v) => {
                                parsed.insert(real.clone(), Value::Array(vec![v]));
                            }
                            None => {}
                        }
                    }
                    (
                        real.clone(),
                        flag,
                        is_list,
                        Process::None, // unknown uses JSON parse fallback inline
                        Callback::None,
                        real,
                    )
                };

            if callback == Callback::Help {
                return Err(CliError {
                    exit_code: 0,
                    message: get_help_text(options),
                });
            } else if callback == Callback::Version {
                return Err(CliError {
                    exit_code: 0,
                    message: version_text(),
                });
            } else if flag {
                let v = if option_name.starts_with("--no-") {
                    Value::Bool(false)
                } else if let Some(v) = value {
                    Value::Bool(v == "1")
                } else {
                    Value::Bool(true)
                };
                parsed.insert(key, v);
            } else {
                // Non-flag option.
                let mut val = value;
                if val.is_none() && i + 1 < args.len() && !is_option(&args[i + 1]) {
                    val = Some(args[i + 1].clone());
                    i += 1;
                }
                if let Some(v) = val {
                    let processed = if process == Process::None && !prepared.by_token.contains_key(&option_name) {
                        // Unknown option: JSON parse fallback.
                        json_parse_fallback(&v)
                    } else {
                        apply_process(process, &v)?
                    };
                    if list {
                        let arr = parsed
                            .get_mut(&key)
                            .expect("list option must be seeded");
                        if let Value::Array(a) = arr {
                            a.push(processed);
                        } else {
                            *arr = Value::Array(vec![processed]);
                        }
                    } else {
                        parsed.insert(key, processed);
                    }
                } else {
                    parsed.insert(key.clone(), Value::Null);
                    missing.push(key);
                }
            }
            // silence unused
            let _ = full;
        } else {
            positional.push(positional_value(arg));
        }
        i += 1;
    }

    // Report missing values for KNOWN options only (baseline only looks up
    // options[name].full; unknown keys would throw, matching baseline crash only
    // for known options). Replicate the known-option check.
    for name in &missing {
        if let Some(o) = options.iter().find(|o| &o.key == name) {
            let msg = format!(
                "Missing value: --{} requires a value\n\n---\n\n{}",
                o.full,
                get_help_text(options)
            );
            return Err(CliError {
                exit_code: 1,
                message: msg,
            });
        }
    }

    validate_options(&parsed, options)?;

    Ok(ParseResult {
        positional_arguments: positional,
        options: parsed,
    })
}

fn validate_options(parsed: &Map<String, Value>, options: &[OptionDef]) -> Result<(), CliError> {
    let mut errors: Vec<String> = Vec::new();
    for o in options {
        if let Some(choices) = &o.choices {
            let val = parsed.get(&o.key);
            let ok = match val {
                Some(v) => choices.contains(v),
                None => false,
            };
            if !ok {
                let choices_str = choices
                    .iter()
                    .map(display_value)
                    .collect::<Vec<_>>()
                    .join(",");
                errors.push(format!(
                    "Error: --{} must be one of the values {}",
                    o.full, choices_str
                ));
            }
        }
    }
    if !errors.is_empty() {
        Err(CliError {
            exit_code: 1,
            message: format!("{}\n\n---\n\n{}", errors.join("\n"), get_help_text(options)),
        })
    } else {
        Ok(())
    }
}

/// JS `String(value)` style rendering for help/choices display.
fn display_value(v: &Value) -> String {
    match v {
        Value::Bool(b) => b.to_string(),
        Value::Number(n) => {
            if let Some(i) = n.as_i64() {
                i.to_string()
            } else if let Some(f) = n.as_f64() {
                format_float(f)
            } else {
                n.to_string()
            }
        }
        Value::String(s) => s.clone(),
        _ => v.to_string(),
    }
}

fn format_float(f: f64) -> String {
    if f.fract() == 0.0 {
        format!("{}", f as i64)
    } else {
        format!("{}", f)
    }
}

fn format_option(o: &OptionDef) -> String {
    let mut text = String::from("  ");
    match &o.abbr {
        Some(abbr) => text.push_str(&format!("-{}, ", abbr)),
        None => text.push_str("    "),
    }
    text.push_str("--");
    if o.flag {
        text.push_str("(no-)");
    }
    text.push_str(&o.full);
    if let Some(choices) = &o.choices {
        text.push('=');
        text.push_str(
            &choices
                .iter()
                .map(display_value)
                .collect::<Vec<_>>()
                .join("|"),
        );
    } else if let Some(mv) = &o.metavar {
        text.push_str(&format!("={}", mv));
    }
    if o.list {
        text.push_str(" ...");
    }
    if o.default_help.is_some() || o.default.is_some() || o.help.is_some() {
        text.push_str("  ");
        while text.len() < 32 {
            text.push(' ');
        }
        let text_length = text.len();
        if let Some(help) = &o.help {
            text.push_str(help);
        }
        if o.default_help.is_some() || o.default.is_some() {
            if o.help.is_some() {
                text.push('\n');
            }
            text.push_str(&" ".repeat(text_length));
            text.push_str("(default: ");
            match &o.default_help {
                Some(dh) => text.push_str(dh),
                None => match &o.default {
                    Some(d) => text.push_str(&display_value(d)),
                    None => {}
                },
            }
            text.push(')');
        }
    }
    text
}

pub fn get_help_text(options: &[OptionDef]) -> String {
    let mut opts: Vec<&OptionDef> = options.iter().collect();
    opts.sort_by_key(|o| o.display_index);

    let mut body = String::new();
    for (i, o) in opts.iter().enumerate() {
        if i > 0 {
            body.push('\n');
        }
        body.push_str(&format_option(o));
    }

    let text = format!(
        "\nUsage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n{}\n",
        body
    );
    text.trim_start_matches('\n').to_string()
}

/// Version banner mirroring the JS `--version` callback output.
pub fn version_text() -> String {
    let pkg_root = crate::runner::package_root();
    let version = crate::runner::package_version(&pkg_root, "jscodeshift").unwrap_or_else(|| "unknown".into());
    let babel = crate::runner::package_version(&pkg_root, "@babel/core").unwrap_or_else(|| "unknown".into());
