{"command":"create","file_text":"//! Port of `src/ignoreFiles.js` plus a picomatch-compatible matcher.
//!
//! The matcher reproduces the subset of `picomatch.isMatch` semantics that
//! `ignoreFiles` and file discovery rely on, using `globset` under the hood.
//! Windows path separators are normalized to `/` like the JS baseline.

use globset::{Glob, GlobSet, GlobSetBuilder};
use std::path::Path;

/// Compile a single glob pattern into a `GlobSet` that matches the same set of
/// paths that `picomatch.isMatch(path, [pattern], {dot:true})` would match.
pub fn compile_matcher(patterns: &[String]) -> Option<GlobSet> {
    if patterns.is_empty() {
        return None;
    }
    let mut builder = GlobSetBuilder::new();
    for p in patterns {
        for variant in pattern_variants(p) {
            if let Ok(g) = Glob::new(&variant) {
                let _ = builder.add(g);
            }
        }
    }
    builder.build().ok()
}

/// picomatch-equivalent glob variants for a single pattern.
fn pattern_variants(pattern: &str) -> Vec<String> {
    let mut variants = Vec::new();
    if let Some(rest) = pattern.strip_prefix("**/") {
        // **/X matches both X (at root) and a/b/X
        variants.push(rest.to_string());
        variants.push(format!("**/{}", rest));
    } else if let Some(rest) = pattern.strip_suffix("/**") {
        // X/** matches X and X/**
        variants.push(rest.to_string());
        variants.push(format!("{}/**", rest));
    } else if pattern.starts_with("**/") && pattern.ends_with("/**") {
        variants.push(pattern.to_string());
    } else {
        variants.push(pattern.to_string());
    }
    variants
}

/// Normalize a path's separators to `/`, like picomatch on POSIX inputs.
pub fn normalize_sep(path: &str) -> String {
    path.replace('\\', "/")
}

/// `shouldIgnore`-style matcher with the leading-traversal-prefix stripping
/// behavior described in ignoreFiles.js (issue #556).
pub fn should_ignore(path: &str, set: Option<&GlobSet>) -> bool {
    match set {
        None => false,
        Some(s) => {
            let normalized = normalize_sep(path);
            if s.is_match(&normalized) {
                return true;
            }
            // strip leading ./ ../  ./.. traversal prefixes
            let stripped = strip_leading_traversal(&normalized);
            if stripped != normalized {
                return s.is_match(stripped);
            }
            false
        }
    }
}

fn strip_leading_traversal(path: &str) -> &str {
    let bytes = path.as_bytes();
    let mut i = 0;
    loop {
        let start = i;
        if bytes[i..].starts_with(b"./") {
            i += 2;
        } else if bytes[i..].starts_with(b"../") {
            i += 3;
        } else if bytes[i..] == b"." || bytes[i..] == b".." {
            i += bytes[i..].len();
        } else {
            return &path[start..];
        }
    }
}

/// In-memory representation of the ignore-pattern set built by ignoreFiles.js.
pub struct IgnoreSet {
    matchers: Vec<String>,
    compiled: Option<GlobSet>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        IgnoreSet {
            matchers: Vec::new(),
            compiled: None,
        }
    }

    /// `addIgnorePattern` from ignoreFiles.js.
    pub fn add_pattern(&mut self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val;
        if !pattern.contains('/') {
            self.matchers.push(format!("**/{}", pattern));
        } else if pattern.ends_with('/') {
            self.matchers.push(format!("**/{}**", pattern));
            self.matchers.push(format!("{}**", pattern));
        }
        self.matchers.push(pattern.to_string());
    }

    pub fn add_from_input(&mut self, input: Option<&Vec<String>>) {
        if let Some(v) = input {
            for p in v {
                self.add_pattern(p);
            }
        }
    }

    /// Reads each config file and adds its non-comment lines as patterns.
    pub fn add_from_file(&mut self, input: Option<&Vec<String>>) -> std::io::Result<()> {
        if let Some(files) = input {
            for config in files {
                let p = Path::new(config);
                if p.is_file() {
                    let content = std::fs::read_to_string(p)?;
                    for line in content.split('\n') {
                        // split on \r?\n -- drop trailing \r
                        let line = line.trim_end_matches('\r');
                        self.add_pattern(line);
                    }
                }
            }
        }
        Ok(())
    }

    pub fn rebuild(&mut self) {
        self.compiled = compile_matcher(&self.matchers);
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        should_ignore(path, self.compiled.as_ref())
    }

    pub fn is_empty(&self) -> bool {
        self.matchers.is_empty()
    }
}","path":"/workspace/src/glob.rs"}

