/**
 * Transform host bridge for the Rust port of jscodeshift.
 *
 * The Rust CLI spawns one `node bridge/transform-host.js` process per worker
 * (or, in `--run-in-band` mode, a single process), passing the transform file
 * path and a babel flag (`babel` / `no-babel`) as positional arguments -- exactly
 * like the original `Worker.js` was forked with `(transformFile, 'babel'|...)`.
 *
 * Communication uses newline-delimited JSON over stdio (a `message` per line on
 * stdout, with stderr reserved for fatal diagnostics). The host receives:
 *
 *   {"files":[...], "options":{...}}
 *
 * and emits one message per processed file plus a final `free`:
 *
 *   {"action":"status","status":"ok|nochange|skip|error","msg":"..."}
 *   {"action":"update","name":"...","quantity":N}
 *   {"action":"report","file":"...","msg":"..."}
 *   {"action":"free"}
 *
 * This preserves the observable behavior of the original worker: it loads the
 * transform module (optionally via @babel/register), parses each source file
 * with the configured parser, runs the user transform, compares the output,
 * writes the file (unless dry), and reports per-file status. The Rust side
 * owns the stats/counters/timing/printing so output formatting is unchanged.
 */

'use strict';

const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');
const getParser = require('./getParser.js');
const jscodeshift = require('./core.js');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

let transform;
let parserFromTransform;
let buffer = '';

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([presetEnv.default, { targets: { node: true } }]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const module = require(tr);
  transform = typeof module.default === 'function' ? module.default : module;
  if (module.parser) {
    parserFromTransform =
      typeof module.parser === 'string' ? getParser(module.parser) : module.parser;
  }
}

function prepareJscodeshift(options) {
  const parser =
    parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function send(data) {
  process.stdout.write(JSON.stringify(data) + '\n');
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({ action: 'status', status, msg });
}

function report(file, msg) {
  send({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({ action: 'update', name, quantity });
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = trace.split('\n');
  const result = [];
  lines.every(function (line) {
    if (line.indexOf(__filename) === -1) {
      result.push(line);
      return true;
    }
  });
  return result.join('\n');
}

function free() {
  send({ action: 'free' });
}

async function run(data) {
  const files = data.files;
  const options = data.options || {};
  if (!files || files.length === 0) {
    free();
    return;
  }
  const pending = files.slice();
  let outstanding = pending.length;

  function done() {
    outstanding--;
    if (outstanding === 0) free();
  }

  for (const file of pending) {
    fs.readFile(file, async function (err, source) {
      if (err) {
        updateStatus('error', file, 'File error: ' + err);
        done();
        return;
      }
      source = source.toString();
      try {
        const j = prepareJscodeshift(options);
        const out = await transform(
          { path: file, source },
          {
            j,
            jscodeshift: j,
            stats: options.dry ? stats : empty,
            report: (msg) => report(file, msg),
          },
          options
        );
        if (!out || out === source) {
          updateStatus(out ? 'nochange' : 'skip', file);
          done();
          return;
        }
        if (options.print) {
          process.stderr.write(out); // print output goes to console.log in JS;
          // to keep stdout free for IPC, the Rust host intercepts print via a
          // dedicated message. We mirror original behavior by emitting a
          // 'print' message instead.
          send({ action: 'print', out });
        }
        if (!options.dry) {
          writeFileAtomic(file, out, function (werr) {
            if (werr) {
              updateStatus('error', file, 'File writer error: ' + werr);
            } else {
              updateStatus('ok', file);
            }
            done();
          });
        } else {
          updateStatus('ok', file);
          done();
        }
      } catch (terr) {
        updateStatus(
          'error',
          file,
          'Transformation error (' +
            terr.message.replace(/\n/g, ' ') +
            ')\n' +
            trimStackTrace(terr.stack)
        );
        done();
      }
    });
  }
}

