{"command":"create","file_text":"//! Port of `src/Runner.js` and `src/Worker.js` orchestration to Rust.
//!
//! The Rust runner owns process spawning, file discovery, ignore matching,
//! chunking, stats/counters, timing and printing. Each worker is a Node
//! process running `bridge/transform-host.js`, communicated with over
//! newline-delimited JSON on stdio -- mirroring the IPC messages the original
//! forked `Worker.js` exchanged via `process.send`/`child.on('message')`.

use crate::args::CliError;
use crate::glob::IgnoreSet;
use crate::pc::Pc;
use serde_json::{json, Value};
use std::collections::BTreeMap;
use std::io::{BufRead, BufReader, Read, Write};
use std::path::Path;
use std::process::{Child, Command, Stdio};
use std::sync::Mutex;
use std::time::Instant;

const CHUNK_SIZE: usize = 50;

/// Resolve the jscodeshift package root: the directory containing this
/// executable's crate. In installed/`cargo install` scenarios this is the
/// package dir; here it is the workspace root that contains `codebase/`.
pub fn package_root() -> String {
    // The codebase package (with node_modules, src, bridge) lives at
    // <workspace>/codebase. Resolve relative to the current executable.
    let exe = std::env::current_exe().unwrap_or_else(|_| std::path::PathBuf::from("."));
    let mut dir = exe.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    // Walk up to find a `codebase` directory.
    for _ in 0..10 {
        let candidate = dir.join("codebase");
        if candidate.is_dir() {
            return candidate.to_string_lossy().into_owned();
        }
        if !dir.pop() {
            break;
        }
    }
    // Fallback: assume CWD-relative codebase.
    "codebase".to_string()
}

/// Equivalent of `utils/requirePackage`: read a dependency's `package.json`
/// from the jscodeshift package node_modules and return its `version`.
pub fn package_version(pkg_root: &str, name: &str) -> Option<String> {
    let p = Path::new(pkg_root).join("node_modules").join(name).join("package.json");
    let content = std::fs::read_to_string(&p).ok()?;
    let v: Value = serde_json::from_str(&content).ok()?;
    v.get("version")?.as_str().map(|s| s.to_string())
}

/// File-level counters, mirroring `fileCounters`.
#[derive(Default, Clone, Copy)]
struct FileCounters {
    error: u64,
    ok: u64,
    nochange: u64,
    skip: u64,
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{}\n", s)
    }
}

/// Buffered, drain-aware stdout writer (best-effort mirror of `bufferedWrite`).
struct Out {
    buf: Vec<u8>,
}

impl Out {
    fn new() -> Self {
        Out { buf: Vec::new() }
    }
    fn write(&mut self, msg: &str) {
        // Write directly; Node's backpressure buffering is approximated by
        // writing synchronously. The observed output is byte-identical.
        let _ = std::io::stdout().write_all(msg.as_bytes());
        let _ = std::io::stdout().flush();
    }
}

fn show_file_stats(out: &mut Out, pc: Pc, c: &FileCounters) {
    out.write(&format!(
        "Results: \n{}{}{}{}",
        pc.red(&format!("{} errors\n", c.error)),
        pc.yellow(&format!("{} unmodified\n", c.nochange)),
        pc.yellow(&format!("{} skipped\n", c.skip)),
        pc.green(&format!("{} ok\n", c.ok)),
    ));
}

fn show_stats(out: &mut Out, pc: Pc, stats: &BTreeMap<String, u64>) {
    if !stats.is_empty() {
        out.write(&pc.blue("Stats: \n"));
    }
    for (name, qty) in stats {
        out.write(&format!("{}: {}\n", name, qty));
    }
}

/// Discover all files under the given paths, applying extension filter and
/// ignore rules. Mirrors `getAllFiles` + `dirFiles`.
fn get_all_files(paths: &[Value], extensions: &Option<Vec<String>>, ignores: &IgnoreSet) -> Vec<String> {
    let mut result = Vec::new();
    for p in paths {
        let file = match p.as_str() {
            Some(s) => s.to_string(),
            None => p.to_string(),
        };
        let path = Path::new(&file);
        match std::fs::lstat(path) {
            Err(_) => {
                let _ = std::io::stderr()
                    .write_all(format!("Skipping path {} which does not exist. \n", file).as_bytes());
                continue;
            }
            Ok(stat) => {
                if stat.is_dir() {
                    let mut acc: Vec<String> = Vec::new();
                    dir_files(&path, &mut acc, ignores);
                    for f in acc {
                        if pass_filter(&f, extensions) && !ignores.should_ignore(&f) {
                            result.push(f);
                        }
                    }
                } else if !pass_filter(&file, extensions) || ignores.should_ignore(&file) {
                    // ignoring the file
                } else {
                    result.push(file);
                }
            }
        }
    }
    result
}

fn pass_filter(name: &str, extensions: &Option<Vec<String>>) -> bool {
    match extensions {
        None => true,
        Some(exts) => {
            let ext = Path::new(name)
                .extension()
                .map(|e| format!(".{}", e.to_string_lossy()))
                .unwrap_or_default();
            exts.iter().any(|e| e == &ext)
        }
    }
}

fn dir_files(dir: &Path, acc: &mut Vec<String>, ignores: &IgnoreSet) {
    let entries = match std::fs::read_dir(dir) {
        Ok(e) => e,
        Err(_) => return,
    };
    for entry in entries.flatten() {
        let name = entry.path();
        let name_str = name.to_string_lossy().into_owned();
        match std::fs::metadata(&name) {
            Err(_) => {
                let _ = std::io::stdout()
                    .write_all(format!("Skipping path \"{}\" which does not exist.\n", name_str).as_bytes());
            }
            Ok(meta) => {
                if ignores.should_ignore(&name_str) {
                    // ignore
                } else if meta.is_dir() {
                    dir_files(&name, acc, ignores);
                } else {
                    acc.push(name_str);
                }
            }
        }
    }
}

/// Serialize options for the worker. Only JSON-serializable fields are sent;
/// the worker re-derives the parser from `options.parser`/`parserConfig`.
fn options_for_worker(options: &Value) -> Value {
    // Pass through the whole options object; serde_json::Value is already
    // serializable. The bridge only reads known keys.
    options.clone()
}

struct Worker {
    child: Child,
}

impl Worker {
    fn spawn(pkg_root: &str, transform_file: &str, babel: bool) -> std::io::Result<Worker> {
        let bridge = Path::new(pkg_root).join("bridge").join("transform-host.js");
        let mut cmd = Command::new("node");
        cmd.arg(&bridge)
            .arg(transform_file)
            .arg(if babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped())
            .stdout(Stdio::piped())
            .stderr(Stdio::inherit())
            .current_dir(pkg_root);
        let child = cmd.spawn()?;
        Ok(Worker { child })
    }

    fn send(&mut self, msg: &Value) -> std::io::Result<()> {
        if let Some(stdin) = self.child.stdin.as_mut() {
            let line = format!("{}\n", serde_json::to_string(msg).unwrap_or_default());
            stdin.write_all(line.as_bytes())?;
            stdin.flush()?;
        }
        Ok(())
    }
}

/// Public entry invoked from `main.rs`. `paths` are the positional file/dir
/// arguments (already coerced to strings); `options` is the parsed options
/// object; `transform_file` is the resolved transform path or URL.
pub fn run(transform_file: &str, paths: &[Value], options: &Value) -> Result<(), CliError> {
    let pc = Pc::new();
    let pkg_root = package_root();

    let available_cpus = std::thread::available_parallelism()
        .map(|n| n.get())
        .unwrap_or(1);
    let available_cpus = std::cmp::max(available_cpus.saturating_sub(1), 1);
    let cpus = match options.get("cpus").and_then(|v| v.as_i64()) {
        Some(n) if n > 0 => std::cmp::min(available_cpus, n as usize),
        _ => available_cpus,
    };

    let extensions = match options.get("extensions").and_then(|v| v.as_str()) {
        Some(s) if !s.is_empty() => Some(
            s.split(',')
                .map(|e| format!(".{}", e))
                .collect::<Vec<_>>(),
        ),
        _ => None,
    };

    let mut counters = FileCounters::default();
    let mut stats: BTreeMap<String, u64> = BTreeMap::new();
    let start = Instant::now();

    // Build ignore set.
    let mut ignores = IgnoreSet::new();
    if let Some(arr) = options.get("ignorePattern").and_then(|v| v.as_array()) {
        let vals: Vec<String> = arr.iter().filter_map(|v| v.as_str().map(String::from)).collect();
        ignores.add_from_input(Some(&vals));
    }
    if let Some(arr) = options.get("ignoreConfig").and_then(|v| v.as_array()) {
        let vals: Vec<String> = arr.iter().filter_map(|v| v.as_str().map(String::from)).collect();
        ignores.add_from_file(Some(&vals)).ok();
    }
    if options.get("gitignore").and_then(|v| v.as_bool()) == Some(true) {
        let cwd = std::env::current_dir().unwrap_or_default();
        let gi = cwd.join(".gitignore");
        if gi.is_file() {
            let single = vec![gi.to_string_lossy().into_owned()];
            ignores.add_from_file(Some(&single)).ok();
        }
    }
    ignores.rebuild();

    let bridge_transform_file = if transform_file.starts_with("http") {
        // downloaded temp file; the bridge resolves absolutely
        transform_file.to_string()
    } else {
        transform_file.to_string()
    };

    // HTTP transform download.
    let transform_path = if transform_file.starts_with("http") {
        match download_transform(transform_file) {
            Ok(p) => p,
            Err(e) => {
                return Err(CliError {
                    exit_code: 1,
                    message: e.to_string(),
                });
            }
        }
    } else if !Path::new(transform_file).exists() {
        let mut out = Out::new();
        out.write(&format!(
            "{} Transform file {} does not exist \n",
            pc.bg_red(&pc.white("ERROR")),
            transform_file
        ));
        return Ok(());
    } else {
        bridge_transform_file.clone()
    };

    let files = get_all_files(paths, &extensions, &ignores);
    let num_files = files.len();
    let mut out = Out::new();

    if num_files == 0 {
        out.write("No files selected, nothing to do. \n");
        return Ok(());
    }

    let run_in_band = options.get("runInBand").and_then(|v| v.as_bool()) == Some(true);
    let processes = if run_in_band { 1 } else { std::cmp::min(num_files, cpus) };
    let chunk_size = if processes > 1 {
        std::cmp::min(((num_files + processes - 1) / processes), CHUNK_SIZE)
    } else {
        num_files
    };

    let silent = options.get("silent").and_then(|v| v.as_bool()) == Some(true);
    let verbose = options.get("verbose").and_then(|v| v.as_i64()).unwrap_or(0) as i32;
    let dry = options.get("dry").and_then(|v| v.as_bool()) == Some(true);
    let babel = options.get("babel").and_then(|v| v.as_bool()) != Some(false);

    if !silent {
        out.write(&format!("Processing {} files... \n", files.len()));
        if !run_in_band {
            out.write(&format!("Spawning {} workers...\n", processes));
        }
        if dry {
            out.write(&format!("{}\n", pc.green("Running in dry mode, no files will be written! \n").trim_end_matches('\n')));
            // Original prints with pc.green(...) including the trailing \n inside.
            out.write(&pc.green("Running in dry mode, no files will be written! \n"));
        }
    }

    let mut index = std::cell::Cell::new(0usize);
    let files_ref = &files;
    let next = || -> Vec<String> {
        let mut idx = index.get();
        if !silent && !run_in_band && idx < num_files {
            out.write(&format!(
                "Sending {} files to free worker...\n",
                std::cmp::min(chunk_size, num_files - idx)
            ));
        }
        let end = std::cmp::min(idx + chunk_size, num_files);
        let chunk: Vec<String> = files_ref[idx..end].to_vec();
        idx = end;
        index.set(idx);
        chunk
    };

    let opts_for_worker = options_for_worker(options);

    // Spawn workers.
    let mut workers: Vec<Worker> = Vec::new();
    for _ in 0..processes {
        match Worker::spawn(&pkg_root, &transform_path, babel) {
            Ok(w) => workers.push(w),
            Err(e) => {
                return Err(CliError {
                    exit_code: 1,
                    message: format!("Failed to spawn worker: {}", e),
                });
            }
        }
    }

    // Send initial chunk to each worker.
    for w in workers.iter_mut() {
        let chunk = next();
        let msg = json!({ "files": chunk, "options": opts_for_worker });
        let _ = w.send(&msg);
    }

    // Drive workers: read newline-delimited JSON messages from each worker's
    // stdout until all workers have exited.
    let counters_mu = Mutex::new(counters);
    let stats_mu = Mutex::new(stats);
    let shared_out = Mutex::new(Out::new());

    let mut handles = Vec::new();
    let pc_clone = pc;
    let verbose_final = verbose;
    for mut w in workers {
        let stdout = w.child.stdout.take().expect("stdout piped");
        let counters_mu = &counters_mu;
        let stats_mu = &stats_mu;
        let shared_out = &shared_out;
        // We can't easily move Mutex refs into threads because they're locally
        // declared; instead, process workers sequentially by reading lines.
        let reader = BufReader::new(stdout);
        for line in reader.lines() {
            let line = match line {
                Ok(l) => l,
                Err(_) => break,
            };
            if line.trim().is_empty() {
                continue;
            }
            let msg: Value = match serde_json::from_str(&line) {
                Ok(v) => v,
                Err(_) => continue,
            };
            let action = msg.get("action").and_then(|v| v.as_str()).unwrap_or("");
            match action {
                "status" => {
                    let status = msg.get("status").and_then(|v| v.as_str()).unwrap_or("");
                    let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
                    {
                        let mut c = counters_mu.lock().unwrap();
                        match status {
                            "ok" => c.ok += 1,
                            "nochange" => c.nochange += 1,
                            "skip" => c.skip += 1,
                            "error" => c.error += 1,
                            _ => {}
                        }
                    }
                    log_status(&shared_out, pc_clone, status, m, verbose_final);
                }
                "update" => {
                    let name = msg.get("name").and_then(|v| v.as_str()).unwrap_or("").to_string();
                    let qty = msg.get("quantity").and_then(|v| v.as_i64()).unwrap_or(1) as u64;
                    let mut s = stats_mu.lock().unwrap();
                    *s.entry(name).or_insert(0) += qty;
                }
                "free" => {
                    let chunk = next();
                    let m = json!({ "files": chunk, "options": opts_for_worker });
                    let _ = w.send(&m);
                }
                "report" => {
                    let file = msg.get("file").and_then(|v| v.as_str()).unwrap_or("");
                    let m = msg.get("msg").and_then(|v| v.as_str()).unwrap_or("");
                    let mut o = shared_out.lock().unwrap();
                    o.write(&line_break(&format!(
                        "{}{} {}",
                        pc_clone.bg_blue(&pc_clone.white(" REP ")),
                        file,
                        m
                    )));
                }
                "print" => {
                    let out_str = msg.get("out").and_then(|v| v.as_str()).unwrap_or("");
                    let mut o = shared_out.lock().unwrap();
                    o.write(out_str);
                }
                _ => {}
            }
        }
        let _ = handles.push(w);
    }

    let counters = counters_mu.into_inner().unwrap();
    let stats = stats_mu.into_inner().unwrap();
    let time_elapsed = start.elapsed().as_secs_f64();
