        }
    }

    let _ = (handles, opts_for_worker);
    Ok(())
}

fn log_status(out: &Mutex<Out>, pc: Pc, status: &str, msg: &str, verbose: i32) {
    let mut o = out.lock().unwrap();
    match status {
        "ok" => {
            if verbose >= 2 {
                o.write(&format!("{}{}", pc.bg_green(&pc.white(" OKK ")), line_break(msg)));
            }
        }
        "nochange" => {
            if verbose >= 1 {
                o.write(&format!("{}{}", pc.bg_yellow(&pc.white(" NOC ")), line_break(msg)));
            }
        }
        "skip" => {
            if verbose >= 1 {
                o.write(&format!("{}{}", pc.bg_yellow(&pc.white(" SKIP ")), line_break(msg)));
            }
        }
        "error" => {
            if verbose >= 0 {
                o.write(&format!("{}{}", pc.bg_red(&pc.white(" ERR ")), line_break(msg)));
            }
        }
        _ => {}
    }
}

