{"command":"create","file_text":"//! jscodeshift CLI entry point.
//!
//! Mirrors `bin/jscodeshift.js`: parse args (with help/version short-circuit),
//! resolve the transform, read paths from stdin or positional args, and hand
//! off to the runner.

use jscodeshift::args;
use jscodeshift::runner;
use std::io::{Read, Write};

fn main() {
    let raw: Vec<String> = std::env::args().skip(1).collect();

    match args::parse(&args::cli_options(), &raw) {
        Ok(result) => {
            let options = &result.options;
            let transform_file = options
                .get("transform")
                .and_then(|v| v.as_str())
                .unwrap_or("./transform.js")
                .to_string();

            let paths = if options.get("stdin").and_then(|v| v.as_bool()) == Some(true) {
                read_stdin_paths()
            } else {
                result.positional_arguments.clone()
            };

            match runner::run(&transform_file, &paths, &serde_json::Value::Object(options.clone())) {
                Ok(()) => {}
                Err(e) => {
                    if e.exit_code == 0 {
                        // help/version
                        let _ = std::io::stdout().write_all(e.message.as_bytes());
                    } else {
                        let _ = std::io::stderr().write_all(e.message.as_bytes());
                    }
                    std::process::exit(e.exit_code);
                }
            }
        }
        Err(e) => {
            if e.exit_code == 0 {
                let _ = std::io::stdout().write_all(e.message.as_bytes());
            } else {
                let _ = std::io::stderr().write_all(e.message.as_bytes());
            }
            std::process::exit(e.exit_code);
        }
    }
}

fn read_stdin_paths() -> Vec<serde_json::Value> {
    let mut input = String::new();
    let _ = std::io::stdin().read_to_string(&mut input);
    input
        .lines()
        .filter(|l| !l.trim().is_empty())
        .map(|l| serde_json::Value::String(l.to_string()))
        .collect()
}","path":"/workspace/src/main.rs"}

