{"command":"str_replace","new_str":"/// Equivalent of `utils/requirePackage`: resolve `name`, then walk up from
/// the entry's directory to find the nearest `package.json` whose `name`
/// matches, returning its `version`. For the jscodeshift package itself,
/// `pkg_root/package.json` is read directly (mirroring `require('../package.json')`).
pub fn package_version(pkg_root: &str, name: &str) -> Option<String> {
    // jscodeshift's own version comes from the package root's package.json,
    // exactly like `bin/jscodeshift.js` does `require('../package.json')`.
    if name == "jscodeshift" {
        let p = Path::new(pkg_root).join("package.json");
        if let Ok(content) = std::fs::read_to_string(&p) {
            if let Ok(v) = serde_json::from_str::<Value>(&content) {
                if let Some(s) = v.get("version").and_then(|x| x.as_str()) {
                    return Some(s.to_string());
                }
            }
        }
        return None;
    }
    // Mirror requirePackage: find the dependency's main entry, then walk up
    // to the nearest package.json whose `name` field matches `name`.
    let nm = Path::new(pkg_root).join("node_modules").join(name);
    let pkg_json = nm.join("package.json");
    let main_entry = if let Ok(content) = std::fs::read_to_string(&pkg_json) {
        if let Ok(v) = serde_json::from_str::<Value>(&content) {
            v.get("main")
                .and_then(|x| x.as_str())
                .map(|s| nm.join(s))
                .unwrap_or_else(|| nm.join("index.js"))
        } else {
            nm.join("index.js")
        }
    } else {
        // Fallback: read directly from the dependency's package.json.
        let p = Path::new(pkg_root).join("node_modules").join(name).join("package.json");
        let content = std::fs::read_to_string(&p).ok()?;
        let v: Value = serde_json::from_str(&content).ok()?;
        return v.get("version")?.as_str().map(|s| s.to_string());
    };

    let mut dir = main_entry.parent().map(|p| p.to_path_buf()).unwrap_or_default();
    loop {
        let candidate = dir.join("package.json");
        if let Ok(content) = std::fs::read_to_string(&candidate) {
            if let Ok(v) = serde_json::from_str::<Value>(&content) {
                if v.get("name").and_then(|x| x.as_str()) == Some(name) {
                    return v.get("version").and_then(|x| x.as_str()).map(|s| s.to_string());
                }
            }
        }
        if !dir.pop() {
            break;
        }
    }
    None
}","old_str":"/// Equivalent of `utils/requirePackage`: read a dependency's `package.json`
